/**
 * Lightweight Standalone SVG Chart Engine — Manifest V3 CSP Compliant
 * ApexCharts-compatible API supporting 'radialBar', 'bar' (horizontal), and 'area'.
 */
(function (global) {
  'use strict';

  let chartIdCounter = 0;

  class ApexCharts {
    constructor(element, options = {}) {
      this.el = typeof element === 'string' ? document.querySelector(element) : element;
      this.options = options;
      this.chartId = `outfox-chart-${++chartIdCounter}`;
    }

    render() {
      if (!this.el) return Promise.resolve();
      this.el.innerHTML = '';
      const type = this.options.chart?.type || 'bar';

      if (type === 'radialBar') {
        this._renderRadialBar();
      } else if (type === 'area') {
        this._renderArea();
      } else {
        this._renderBar();
      }
      return Promise.resolve();
    }

    destroy() {
      if (this.el) this.el.innerHTML = '';
    }

    updateOptions(newOptions = {}) {
      this.options = { ...this.options, ...newOptions };
      return this.render();
    }

    updateSeries(newSeries = []) {
      this.options.series = newSeries;
      return this.render();
    }

    _renderRadialBar() {
      const seriesVal = Array.isArray(this.options.series) ? Number(this.options.series[0]) || 0 : 0;
      const pct = Math.min(100, Math.max(0, seriesVal));
      const radius = 70;
      const circumference = 2 * Math.PI * radius;
      const offset = circumference - (pct / 100) * circumference;

      const colors = this.options.colors || ['#5A45FF', '#00F298'];
      const c1 = colors[0] || '#5A45FF';
      const c2 = colors[1] || '#00F298';

      const totalFormatter = this.options.plotOptions?.radialBar?.dataLabels?.total?.formatter;
      const centerLabel = totalFormatter ? totalFormatter() : `${pct}%`;
      const nameLabel = this.options.labels?.[0] || 'Daily Limit';

      const svg = `
        <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;width:100%;height:100%;min-height:220px;">
          <svg viewBox="0 0 200 200" width="100%" height="200" style="overflow:visible;max-width:240px;">
            <defs>
              <linearGradient id="${this.chartId}-grad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="${c1}" />
                <stop offset="100%" stop-color="${c2}" />
              </linearGradient>
              <filter id="${this.chartId}-glow" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="4" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>
            <!-- Background Track -->
            <circle cx="100" cy="100" r="${radius}" stroke="rgba(255, 255, 255, 0.08)" stroke-width="12" fill="none" />
            <!-- Animated Value Arc -->
            <circle cx="100" cy="100" r="${radius}"
              stroke="url(#${this.chartId}-grad)"
              stroke-width="12"
              fill="none"
              stroke-linecap="round"
              stroke-dasharray="${circumference}"
              stroke-dashoffset="${offset}"
              transform="rotate(-90 100 100)"
              filter="url(#${this.chartId}-glow)"
              style="transition: stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1);" />
            <!-- Centered Text -->
            <text x="100" y="95" text-anchor="middle" font-family="inherit" font-size="22" font-weight="800" fill="#FFFFFF">${centerLabel}</text>
            <text x="100" y="118" text-anchor="middle" font-family="inherit" font-size="11" font-weight="600" fill="#8E87A5">${nameLabel}</text>
          </svg>
        </div>
      `;
      this.el.innerHTML = svg;
    }

    _renderBar() {
      const categories = this.options.xaxis?.categories || [];
      const seriesData = this.options.series?.[0]?.data || [];
      const maxVal = Math.max(...seriesData.map(Number), 1);
      const colors = this.options.colors || ['#5A45FF', '#00C2FF', '#00F298'];

      let rowsHtml = '';
      categories.forEach((cat, idx) => {
        const val = Number(seriesData[idx]) || 0;
        const pct = Math.round((val / maxVal) * 100);
        const prevVal = idx > 0 ? Number(seriesData[idx - 1]) || 0 : 0;
        const convRate = idx > 0 && prevVal > 0 ? `${Math.round((val / prevVal) * 100)}%` : '100%';

        rowsHtml += `
          <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:14px;">
            <div style="display:flex;justify-content:space-between;align-items:center;font-size:12px;">
              <span style="font-weight:600;color:#FFFFFF;">${cat}</span>
              <div style="display:flex;align-items:center;gap:8px;">
                <span style="font-weight:700;color:#FFFFFF;">${val}</span>
                <span style="font-size:10px;font-weight:700;color:#00F298;background:rgba(0,242,152,0.12);padding:1px 6px;border-radius:4px;">${convRate}</span>
              </div>
            </div>
            <div style="height:10px;background:rgba(255,255,255,0.06);border-radius:999px;overflow:hidden;">
              <div style="height:100%;width:${pct}%;border-radius:999px;background:#2563eb;transition:width 0.8s ease;"></div>
            </div>
          </div>
        `;
      });

      this.el.innerHTML = `<div style="padding:10px 4px;">${rowsHtml}</div>`;
    }

    _renderArea() {
      const categories = this.options.xaxis?.categories || ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
      const seriesData = this.options.series?.[0]?.data || [12, 19, 15, 27, 22, 18, 30];
      const maxVal = Math.max(...seriesData.map(Number), 1);
      const minVal = 0;

      const w = 480;
      const h = 180;
      const padL = 35;
      const padR = 20;
      const padT = 20;
      const padB = 30;

      const plotW = w - padL - padR;
      const plotH = h - padT - padB;

      const stepX = categories.length > 1 ? plotW / (categories.length - 1) : plotW;

      const points = seriesData.map((val, idx) => {
        const x = padL + idx * stepX;
        const y = padT + plotH - ((val - minVal) / (maxVal - minVal)) * plotH;
        return { x, y, val, label: categories[idx] };
      });

      // Construct smooth cubic Bezier path
      let d = `M ${points[0].x},${points[0].y}`;
      for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i];
        const p1 = points[i + 1];
        const cx1 = p0.x + (p1.x - p0.x) / 2;
        const cy1 = p0.y;
        const cx2 = p0.x + (p1.x - p0.x) / 2;
        const cy2 = p1.y;
        d += ` C ${cx1},${cy1} ${cx2},${cy2} ${p1.x},${p1.y}`;
      }

      const areaD = `${d} L ${points[points.length - 1].x},${padT + plotH} L ${points[0].x},${padT + plotH} Z`;

      const pointsSvg = points
        .map(
          (p) => `
        <circle cx="${p.x}" cy="${p.y}" r="4" fill="#5A45FF" stroke="#FFFFFF" stroke-width="2" style="cursor:pointer;" />
      `,
        )
        .join('');

      const xLabels = points
        .map(
          (p) => `
        <text x="${p.x}" y="${h - 8}" text-anchor="middle" font-size="10" font-weight="600" fill="#8E87A5">${p.label}</text>
      `,
        )
        .join('');

      const svg = `
        <div style="width:100%;height:100%;display:flex;flex-direction:column;justify-content:center;">
          <svg viewBox="0 0 ${w} ${h}" width="100%" height="100%" style="overflow:visible;">
            <defs>
              <linearGradient id="${this.chartId}-area-grad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stop-color="#5A45FF" stop-opacity="0.5" />
                <stop offset="100%" stop-color="#0D0B18" stop-opacity="0.0" />
              </linearGradient>
            </defs>
            <!-- Grid Lines -->
            <line x1="${padL}" y1="${padT + plotH / 2}" x2="${w - padR}" y2="${padT + plotH / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3 3" />
            <line x1="${padL}" y1="${padT + plotH}" x2="${w - padR}" y2="${padT + plotH}" stroke="rgba(255,255,255,0.08)" />

            <!-- Area Fill -->
            <path d="${areaD}" fill="url(#${this.chartId}-area-grad)" />
            <!-- Line Stroke -->
            <path d="${d}" fill="none" stroke="#5A45FF" stroke-width="3" stroke-linecap="round" />
            <!-- Points -->
            ${pointsSvg}
            <!-- X Labels -->
            ${xLabels}
          </svg>
        </div>
      `;
      this.el.innerHTML = svg;
    }
  }

  global.ApexCharts = ApexCharts;
})(typeof window !== 'undefined' ? window : globalThis);

